values
  ('6d1ec3f1-f387-4592-a221-b23e11af9f12', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', null, 'topic'::public.curated_course_node_type, 'Literary Survey Methods, Iberian Contexts, and Periodization', 'This opening unit teaches students how a literary survey is constructed. Rather than treating periods as neutral containers, students learn to ask who names periods, whose texts become canonical, and how multilingual Iberia complicates a single national story.', 0),
  ('73ba1d71-837c-4dde-9eed-837d149df29e', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', '6d1ec3f1-f387-4592-a221-b23e11af9f12', 'subtopic'::public.curated_course_node_type, 'Survey method and literary history', 'Students learn the purpose and limits of moving chronologically across centuries of literature.', 0),
