  ('28cdbf05-3b85-4471-ae74-8fb8e7b849ec', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', 'a5eda970-ba79-43bc-8c35-1c1dcd8827e2', 'concept'::public.curated_course_node_type, 'historical context', null, 3),
  ('ebe2913e-7c39-4eb2-9ed2-10119f265576', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', null, 'topic'::public.curated_course_node_type, 'Medieval Iberian Texts', 'Medieval texts introduce students to manuscript culture, oral tradition, religious encounter, and early vernacular literary forms. The unit resists treating the Middle Ages as primitive background and instead emphasizes complex cultural production.', 1),
  ('f39f2955-9bce-4b14-b5b3-ba61b3f9cbb4', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', 'ebe2913e-7c39-4eb2-9ed2-10119f265576', 'subtopic'::public.curated_course_node_type, 'Epic, lyric, and oral tradition', 'Students learn how performance, memory, and social values shape early literary forms.', 0),
