  ('2db0570d-52d6-4271-b552-21018560130a', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', 'db31b47b-f96b-4085-985e-8803e06d6329', 'concept'::public.curated_course_node_type, 'comedia audience', null, 3),
  ('85d9ac7e-baf3-4ac7-949d-4dc75ffcb69a', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', null, 'topic'::public.curated_course_node_type, 'Cervantes and the Novel', 'Cervantes becomes a laboratory for fiction: unreliable narration, parody, authorship, embedded stories, and the relation between reading and reality. Students study why Don Quijote remains central while also questioning what that centrality means.', 3),
  ('177b25e0-b14d-49b1-a467-15716455f68f', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', '85d9ac7e-baf3-4ac7-949d-4dc75ffcb69a', 'subtopic'::public.curated_course_node_type, 'Parody and genre consciousness', 'Students learn how Cervantes transforms chivalric romance and earlier narrative traditions.', 0),
