  ('d95ddab1-5667-49fd-95d0-a270bcbf6c59', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', '85d9ac7e-baf3-4ac7-949d-4dc75ffcb69a', 'subtopic'::public.curated_course_node_type, 'Modernity and interpretation', 'Students debate why Cervantes is linked to the modern novel and what that claim includes or excludes.', 2),
