  ('cdab981c-4b54-4bdc-ba5d-36b40912b200', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', 'd95ddab1-5667-49fd-95d0-a270bcbf6c59', 'concept'::public.curated_course_node_type, 'canon and world literature', null, 3),
  ('5a122cf3-fe0d-45c3-b913-27b2f590d855', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', null, 'topic'::public.curated_course_node_type, 'Baroque Poetry and Theater', 'Baroque literature intensifies difficulty, spectacle, and contradiction. Students learn to read dense poetry and theatrical conflict as responses to crisis, power, desire, and religious-political order.', 4),
  ('beb9bf2f-c0d4-4f06-b700-413a67889f0a', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', '5a122cf3-fe0d-45c3-b913-27b2f590d855', 'subtopic'::public.curated_course_node_type, 'Conceptismo and culteranismo', 'Students learn the major poetic styles and why difficulty can be an aesthetic and social strategy.', 0),
