  ('5d14bdf4-7726-4477-bd74-95c0ab301c16', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', null, 'topic'::public.curated_course_node_type, 'Enlightenment, Neoclassicism, and Romanticism', 'This unit follows shifts from reason, reform, and neoclassical order toward Romantic subjectivity, nation, and rebellion. Students connect literature to education, liberalism, gender norms, and political change.', 5),
