  ('9ae7c540-93ea-4977-adc9-01389974fb47', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', null, 'topic'::public.curated_course_node_type, 'Contemporary Spanish Literature and Democratic Spain', 'Post-1975 literature reflects democracy, market culture, regional autonomy, migration, globalization, feminism, memory debates, and new media. Students examine contemporary writing as a site of unresolved historical and social questions.', 9),
