values
  ('7e374807-4b7c-4cb9-87b2-b24a7ac5d8c8', 'f2a3b4c5-6d7e-4f77-8a77-8b9c0d1e2f07', null, 'topic'::public.curated_course_node_type, 'Canon Revision: Women Writers, Regional Literatures, and Marginalized Voices', 'This survey teaches the canon and teaches students to question it. This unit asks what changes when women writers, regional languages, class, sexuality, Roma histories, race, and migration are centered.', 10),
